 let toast=document.querySelector('#toast');if(Number(toast.dataset.time||0)>0){toast.dataset.time=Number(toast.dataset.time)-dt;if(toast.dataset.time<=0)toast.style.opacity=.8}
 if(bots.filter(b=>b.alive).length===0)finish(true);
}
